/*
 * A098973  Primes of the form 5p - 2q where p and q are successive primes
 *          (p<q) ordered by increasing p.
 * https://oeis.org/A098973
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n‑th prime of the form 5·p – 2·q where p and q are
 *            successive primes (p < q). The sequence is generated by
 *            enumerating successive prime pairs (p,q) and testing whether 5p
 *            – 2q is prime
 * Range:     u8 n <= 12, u16 n <= 49, u32 n <= 49, u64 n <= 49, u128 n <= 49,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>

/* ---------- 64‑bit deterministic Miller–Rabin primality test ---------- */
static inline uint64_t modpow(uint64_t a, uint64_t e, uint64_t mod)
{
    uint64_t r = 1;
    a %= mod;
    while (e) {
        if (e & 1)
            r = (unsigned __int128)r * a % mod;
        a = (unsigned __int128)a * a % mod;
        e >>= 1;
    }
    return r;
}

static inline bool miller_rabin_step(uint64_t n, uint64_t s, uint64_t d, uint64_t a)
{
    uint64_t x = modpow(a, d, n);
    if (x == 1 || x == n - 1) return true;
    for (uint64_t r = 1; r < s; ++r) {
        x = (unsigned __int128)x * x % n;
        if (x == n - 1) return true;
    }
    return false;
}

static inline bool is_prime64(uint64_t n)
{
    if (n < 2) return false;

    /* trial division by small primes */
    static const uint64_t small[] = {
        2ULL, 3ULL, 5ULL, 7ULL, 11ULL, 13ULL,
        17ULL, 19ULL, 23ULL, 29ULL, 31ULL, 37ULL
    };
    for (size_t i = 0; i < sizeof(small) / sizeof(small[0]); ++i) {
        uint64_t p = small[i];
        if (n == p) return true;
        if (n % p == 0) return false;
    }

    /* write n-1 as d*2^s with d odd */
    uint64_t d = n - 1, s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    /* deterministic bases for 64-bit integers */
    static const uint64_t bases[] = {
        2ULL, 325ULL, 9375ULL, 28178ULL, 450775ULL, 9780504ULL, 1795265022ULL
    };
    for (size_t i = 0; i < sizeof(bases) / sizeof(bases[0]); ++i) {
        uint64_t a = bases[i] % n;
        if (a == 0) return true;
        if (!miller_rabin_step(n, s, d, a)) return false;
    }
    return true;
}

/* ----------  next prime after a given number ---------- */
static inline uint64_t next_prime(uint64_t n)
{
    if (n < 2) return 2;
    ++n;
    while (!is_prime64(n)) ++n;
    return n;
}

/* ---------- sequence generation ---------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* undefined for offset 0; harmless */

    /* cache of already generated terms */
    static seq_t *terms = NULL;
    static size_t terms_cap = 0;
    static idx_t  terms_used = 0;

    /* current prime pair (p, q) */
    static uint64_t p = 0, q = 0;
    static bool initialized = false;

    /* one‑time initialisation */
    if (!initialized) {
        p = 2;                     /* first prime */
        q = next_prime(p);         /* successive prime */
        terms_cap = 16;
        terms = (seq_t *)malloc(terms_cap * sizeof(seq_t));
        terms_used = 0;
        initialized = true;
    }

    /* grow terms array if required */
    if ((size_t)n > terms_cap) {
        size_t new_cap = terms_cap;
        while ((size_t)n > new_cap) new_cap <<= 1;
        terms = (seq_t *)realloc(terms, new_cap * sizeof(seq_t));
        terms_cap = new_cap;
    }

    /* generate terms until we reach the requested index */
    while (terms_used < n) {
        /* candidate = 5p – 2q */
        seq_t candidate = (seq_t)5 * (seq_t)p - (seq_t)2 * (seq_t)q;

        /* primality test on 64‑bit representation */
        if (is_prime64((uint64_t)candidate))
            terms[terms_used++] = candidate;

        /* advance to the next consecutive prime pair */
        p = q;
        q = next_prime(p);
    }

    return terms[n - 1];
}
